export type ParsedOpenPositionInstruction<
  TProgram extends string = typeof SHORTWIN_SIMPLE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    borrower: TAccountMetas[0];
    config: TAccountMetas[1];
    policy: TAccountMetas[2];
    market: TAccountMetas[3];
    pool: TAccountMetas[4];
    loan: TAccountMetas[5];
    exposure: TAccountMetas[6];
    reference: TAccountMetas[7];
    mint: TAccountMetas[8];
    tokenVault: TAccountMetas[9];
    tokenProgram: TAccountMetas[10];
    feeRecipient: TAccountMetas[11];
    executionAuthority: TAccountMetas[12];
    executionBase: TAccountMetas[13];
    executionWsol: TAccountMetas[14];
    wsolMint: TAccountMetas[15];
    wsolTokenProgram: TAccountMetas[16];
    jupiter: TAccountMetas[17];
    jupiterProgramData: TAccountMetas[18];
    systemProgram: TAccountMetas[19];
    eventAuthority: TAccountMetas[20];
    program: TAccountMetas[21];
  };
  data: OpenPositionInstructionData;
};

export function parseOpenPositionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedOpenPositionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 22) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 22,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      borrower: getNextAccount(),
      config: getNextAccount(),
      policy: getNextAccount(),
      market: getNextAccount(),
      pool: getNextAccount(),
      loan: getNextAccount(),
      exposure: getNextAccount(),
      reference: getNextAccount(),
      mint: getNextAccount(),
      tokenVault: getNextAccount(),
      tokenProgram: getNextAccount(),
      feeRecipient: getNextAccount(),
      executionAuthority: getNextAccount(),
      executionBase: getNextAccount(),
      executionWsol: getNextAccount(),
      wsolMint: getNextAccount(),
      wsolTokenProgram: getNextAccount(),
      jupiter: getNextAccount(),
      jupiterProgramData: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getOpenPositionInstructionDataDecoder().decode(instruction.data),
  };
}
